export const BODY: string = "\n<p>ٹارگٹ فائل سائز کمپریسر وہ ٹول ہے جو تصویر کو آپ کے بتائے ہوئے سائز پر لاتا ہے، جیسے بالکل 100 کلو بائٹ۔ آپ ہدف بتاتے ہیں، ٹول معیار اور سائز کا توازن خود ڈھونڈتا ہے۔</p>\n<p>عام کمپریسر معیار کم کرتا ہے اور سائز جو بھی بنے، وہی دیتا ہے۔ ٹارگٹ کمپریسر الٹا کام کرتا ہے: سائز طے ہے، معیار اس کے مطابق ڈھلتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ ٹارگٹ کمپریشن کیسے کام کرتی ہے، کب استعمال کریں، اور ناممکن ہدف کا کیا کریں۔ استعمال کے لیے <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">ٹارگٹ فائل سائز کمپریسر</a> کھولیں۔</p>\n<h2 id=\"what-is-target-compression\">ٹارگٹ کمپریشن کیا ہے؟</h2>\n<p>ٹارگٹ کمپریشن میں آپ سائز بتاتے ہیں اور ٹول تصویر کو اسی سائز پر لاتا ہے۔ یہ فارم، ای میل اور اپ لوڈ کی حد کے لیے بنایا گیا ہے۔</p>\n<p>ٹارگٹ کمپریشن کا فائدہ یہ ہے کہ آپ کو اندازہ نہیں لگانا پڑتا۔ آپ 200 کلو بائٹ کہتے ہیں اور تصویر 200 کلو بائٹ کی ملتی ہے۔</p>\n<p>ٹارگٹ کمپریشن معیار کو اتنا ہی کم کرتی ہے جتنا ضروری ہو۔ اگر تصویر پہلے سے چھوٹی ہو تو وہ اسے چھوتی بھی نہیں۔</p>\n<h2 id=\"how-it-works\">یہ کیسے کام کرتی ہے؟</h2>\n<p>ٹول پہلے تصویر کو مختلف معیار پر آزماتا ہے اور دیکھتا ہے کہ کون سا معیار ہدف کے قریب لاتا ہے۔ یہ آزمائش بائنری سرچ سے ہوتی ہے۔</p>\n<p>بائنری سرچ میں ٹول معیار کو آدھا کرتا جاتا ہے، جب تک ہدف نہ مل جائے۔ یہ طریقہ تیز اور درست ہے۔</p>\n<p>اگر معیار کم کرنے سے بھی ہدف نہ ملے تو ٹول تصویر کے سائز کو چھوٹا کرتا ہے۔ سائز چھوٹا کرنے سے فائل تیزی سے چھوٹی ہوتی ہے۔</p>\n<h2 id=\"kb-vs-mb\">کلو بائٹ بمقابلہ میگا بائٹ</h2>\n<p>کلو بائٹ اور میگا بائٹ میں فرق سمجھنا ضروری ہے۔ ایک میگا بائٹ میں 1024 کلو بائٹ ہوتے ہیں۔ 100 کلو بائٹ کا مطلب 0.1 میگا بائٹ ہے۔</p>\n<p>سب سے عام غلطی یہ ہے کہ لوگ 100 میگا بائٹ لکھ دیتے ہیں جب انہیں 100 کلو بائٹ چاہیے ہوتا ہے۔ ہدف لکھتے وقت اکائی جانچیں۔</p>\n<p>فارم اکثر کلو بائٹ میں حد بتاتے ہیں، جیسے 200 کلو بائٹ۔ ہدف اسی اکائی میں لکھیں۔</p>\n<h2 id=\"when-to-use-custom\">کسٹم ہدف کب استعمال کریں</h2>\n<p>کسٹم ہدف اس وقت استعمال کریں جب فارم یا سسٹم نے سائز طے کیا ہو، جیسے 100 کلو بائٹ یا 200 کلو بائٹ۔ طے شدہ ہدف اس وقت کام آتا ہے۔</p>\n<p>کسٹم ہدف اس وقت بھی استعمال کریں جب ای میل کی حد ہو۔ ای میل میں بڑی تصویر نہیں جاتی، اس لیے ہدف طے کر کے بھیجیں۔</p>\n<p>اگر کوئی حد نہ ہو تو کسٹم ہدف کی ضرورت نہیں۔ عام کمپریسر کافی ہے۔</p>\n<h2 id=\"binary-search-explained\">بائنری سرچ کی وضاحت</h2>\n<p>بائنری سرچ ایک طریقہ ہے جس میں ٹول معیار کو آدھا کرتا جاتا ہے۔ پہلے 90 فیصد معیار آزماتا ہے، پھر 45، پھر 22، جب تک ہدف نہ مل جائے۔</p>\n<p>بائنری سرچ تیز ہے، کیونکہ ہر قدم میں آدھا راستہ طے ہوتا ہے۔ دس قدموں میں ٹول ہدف کے بہت قریب پہنچ جاتا ہے۔</p>\n<p>بائنری سرچ کی درستگی اس لیے اچھی ہے کہ ٹول ہر قدم میں نتیجہ جانچتا ہے۔ غلطی کی گنجائش بہت کم ہے۔</p>\n<h2 id=\"dimension-scaling\">سائز کم کرنا اور ڈائمینشن</h2>\n<p>جب معیار کم کرنے سے ہدف نہ ملے تو ٹول تصویر کے ڈائمینشن چھوٹے کرتا ہے۔ چھوٹی تصویر کی فائل چھوٹی ہوتی ہے۔</p>\n<p>ڈائمینشن کم کرنے سے تصویر کی تفصیل کم ہوتی ہے، مگر فائل تیزی سے چھوٹی ہوتی ہے۔ یہ آخری حل ہے۔</p>\n<p>ٹول پہلے معیار کم کرتا ہے، پھر ڈائمینشن۔ اس ترتیب سے معیار زیادہ سے زیادہ بچتا ہے۔</p>\n<h2 id=\"impossible-targets\">ناممکن ہدف کا کیا کریں</h2>\n<p>کچھ ہدف ناممکن ہوتے ہیں، جیسے بڑی تصویر کو 10 کلو بائٹ پر لانا۔ اتنی چھوٹی فائل میں تصویر کی تفصیل نہیں بچتی۔</p>\n<p>ناممکن ہدف پر ٹول یا تو قریب ترین سائز دیتا ہے یا بتاتا ہے کہ ہدف ممکن نہیں۔ دونوں صورتوں میں ہدف بڑھائیں۔</p>\n<p>ناممکن ہدف کی پہچان یہ ہے کہ تصویر بہت بڑی ہو اور ہدف بہت چھوٹا۔ اس صورت میں ہدف دوگنا کریں۔</p>\n<h2 id=\"formats-custom\">کسٹم ہدف کے لیے فارمیٹ</h2>\n<p>کسٹم ہدف کے لیے JPG بہترین ہے، کیونکہ اس کا معیار کم کیا جا سکتا ہے۔ PNG کا معیار کم نہیں ہوتا، اس لیے اسے چھوٹا کرنا مشکل ہے۔</p>\n<p>WebP بھی کسٹم ہدف کے لیے اچھا ہے، کیونکہ وہ چھوٹی فائل میں اچھا معیار دیتا ہے۔ لیکن WebP ہر جگہ نہیں کھلتا۔</p>\n<p>اگر فارم JPG مانگتا ہے تو JPG چنیں۔ فارمیٹ بدلنے سے ہدف بدل جاتا ہے۔</p>\n<h2 id=\"batch-custom\">بیچ میں کسٹم ہدف</h2>\n<p>بیچ میں کئی تصویروں کو ایک ہی ہدف پر لایا جا سکتا ہے۔ یہ فارم کے لیے بہت کام آتا ہے، جہاں سب تصویروں کا سائز ایک جیسا چاہیے۔</p>\n<p>بیچ میں ہر تصویر کا معیار الگ ہوتا ہے، کیونکہ ہر تصویر مختلف ہے۔ کچھ تصویریں زیادہ معیار بچاتی ہیں، کچھ کم۔</p>\n<p>بیچ کا نتیجہ ZIP میں ملتا ہے۔ ہر تصویر کو دیکھ کر جانچیں کہ معیار قابل قبول ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی اکائی کی ہے: کلو بائٹ کے بجائے میگا بائٹ لکھ دینا۔ ہدف لکھتے وقت اکائی جانچیں۔</p>\n<p>دوسری غلطی بہت چھوٹا ہدف چننا ہے، جس سے تصویر خراب ہو جاتی ہے۔ ہدف اتنا چھوٹا نہ چنیں کہ تصویر ناقابل استعمال ہو جائے۔</p>\n<p>تیسری غلطی یہ ہے کہ لوگ ہدف کو حتمی سمجھتے ہیں۔ ٹول قریب ترین سائز دیتا ہے، بالکل درست نہیں۔ تھوڑا فرق عام ہے۔</p>\n<h2 id=\"privacy-custom\">رازداری اور کسٹم ہدف</h2>\n<p>ٹارگٹ کمپریسر براؤزر میں چلتا ہے، اس لیے آپ کی تصویر سرور پر نہیں جاتی۔ یہ رازداری کے لیے اہم ہے۔</p>\n<p>حساس تصویر کو بھی ٹارگٹ کمپریسر میں محفوظ طریقے سے کمپریس کیا جا سکتا ہے، کیونکہ فائل آپ کے کمپیوٹر سے باہر نہیں جاتی۔</p>\n<p>رازداری کی تصدیق کے لیے ٹول کو آف لائن آزمائیں۔ اگر وہ آف لائن چلے تو تصویر کہیں نہیں جاتی۔</p>\n<h2 id=\"unit-mistakes\">اکائی کی غلطیاں</h2>\n<p>اکائی کی غلطی سب سے زیادہ نقصان دہ ہے۔ 100 کلو بائٹ اور 100 میگا بائٹ میں ہزار گنا فرق ہے۔</p>\n<p>اکائی جانچنے کا طریقہ یہ ہے کہ ہدف لکھنے سے پہلے فارم کی حد پڑھیں۔ فارم اکثر کلو بائٹ میں حد بتاتا ہے۔</p>\n<p>اگر ہدف غلط اکائی میں لکھا جائے تو نتیجہ یا تو بہت بڑا ہوتا ہے یا بہت چھوٹا۔ دونوں صورتوں میں دوبارہ کرنا پڑتا ہے۔</p>\n<h2 id=\"target-for-email\">ای میل کے لیے ہدف</h2>\n<p>ای میل کے لیے 100 سے 200 کلو بائٹ کا ہدف اچھا ہے۔ اس سائز کی تصویر ای میل میں تیزی سے جاتی ہے۔</p>\n<p>ای میل میں کئی تصویریں ہوں تو ہر ایک کا ہدف 100 کلو بائٹ رکھیں۔ کل سائز 1 میگا بائٹ سے کم رہے۔</p>\n<p>ای میل کے لیے JPG چنیں، کیونکہ وہ چھوٹا اور ہر جگہ کھلتا ہے۔</p>\n<h2 id=\"target-for-print-prep\">پرنٹ کی تیاری کے لیے ہدف</h2>\n<p>پرنٹ کے لیے ہدف بڑا رکھیں، کیونکہ پرنٹ میں تفصیل چاہیے۔ 1 میگا بائٹ سے کم ہدف پرنٹ میں دھندلا ہو جاتا ہے۔</p>\n<p>پرنٹ کے لیے ٹارگٹ کمپریسر کی ضرورت نہیں، کیونکہ پرنٹ میں سائز کی حد نہیں ہوتی۔ عام کمپریسر کافی ہے۔</p>\n<p>اگر پرنٹ شاپ نے سائز کی حد بتائی ہو تو اسی حد کو ہدف بنائیں۔</p>\n<h2 id=\"comparing-targets\">مختلف ہدف کا موازنہ</h2>\n<p>مختلف ہدف آزما کر دیکھیں کہ کون سا معیار دیتا ہے۔ 100 کلو بائٹ اور 200 کلو بائٹ کا فرق دیکھیں۔</p>\n<p>موازنہ کرنے سے آپ کو معلوم ہوتا ہے کہ ہدف کتنا چھوٹا ہو سکتا ہے بغیر معیار گرے۔ یہ تجربہ ایک بار کریں اور یاد رکھیں۔</p>\n<p>موازنہ کے لیے ایک ہی تصویر کو مختلف ہدف پر کمپریس کریں اور دونوں کو ساتھ دیکھیں۔</p>\n<h2 id=\"saving-presets\">پری سیٹ محفوظ کرنا</h2>\n<p>پری سیٹ وہ ہدف ہے جو آپ بار بار استعمال کرتے ہیں، جیسے 100 کلو بائٹ۔ اسے محفوظ کر لیں تاکہ ہر بار نہ لکھنا پڑے۔</p>\n<p>پری سیٹ سے وقت بچتا ہے اور غلطی کم ہوتی ہے۔ ہر فارم کے لیے الگ پری سیٹ رکھیں۔</p>\n<p>پری سیٹ کو نام دیں، جیسے پاسپورٹ یا ای میل، تاکہ یاد رہے کہ کون سا کہاں استعمال ہوتا ہے۔</p>\n<h2 id=\"accessibility-custom\">کسٹم ہدف اور رسائی</h2>\n<p>کسٹم ہدف سے ویب صفحہ تیز لوڈ ہوتا ہے، جو رسائی کے لیے اچھا ہے۔ سست انٹرنیٹ والے صارفین کو چھوٹی تصویر تیزی سے ملتی ہے۔</p>\n<p>رسائی کے لیے تصویر کا سائز چھوٹا رکھیں، مگر اتنا چھوٹا نہیں کہ تفصیل ختم ہو جائے۔ توازن ضروری ہے۔</p>\n<p>ٹارگٹ کمپریسر کا استعمال رسائی بہتر کرتا ہے، کیونکہ وہ ہر تصویر کو ایک ہی حد پر لاتا ہے۔ مزید تفصیل <a href=\"/ur/blog/tasveer-bilkul-exact-kb-tak-kaise-compress-karein/\">بالکل درست کلو بائٹ تک کمپریس کریں</a> میں اور بائنری سرچ کی وضاحت <a href=\"/ur/blog/exact-kb-ke-liye-binary-quality-search/\">بائنری سرچ سے درست ہدف</a> میں دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ٹارگٹ کمپریسر کس سائز کی حد تک کام کرتا ہے؟","answer":"ٹول چند کلو بائٹ سے لے کر کئی میگا بائٹ تک ہدف لے سکتا ہے۔ عملی حد تصویر کے اصل سائز اور فارمیٹ پر منحصر ہے۔ بہت چھوٹا ہدف ناممکن ہو سکتا ہے۔"},{"question":"ٹارگٹ کمپریسر ہدف کے کتنا قریب پہنچتا ہے؟","answer":"ٹول بائنری سرچ سے ہدف کے بہت قریب پہنچتا ہے، عام طور پر چند فیصد کے اندر۔ بالکل درست سائز ہر بار ممکن نہیں، تھوڑا فرق عام ہے۔"},{"question":"کیا میں بیچ میں سب تصویروں کو ایک ہی کسٹم سائز پر لا سکتا ہوں؟","answer":"جی ہاں، بیچ میں سب تصویروں پر ایک ہی ہدف لگتا ہے۔ ہر تصویر کا معیار الگ ہو سکتا ہے، کیونکہ ہر تصویر مختلف ہے۔"},{"question":"اگر تصویر پہلے سے ہدف سے چھوٹی ہو تو کیا ہوتا ہے؟","answer":"ٹول اسے چھوتا نہیں۔ تصویر پہلے سے ہدف سے چھوٹی ہے تو اسے بڑا کرنے کی ضرورت نہیں، وہ ویسے ہی رہتی ہے۔"},{"question":"ٹول ڈائمینشن کم کرنے سے پہلے معیار کیوں آزماتا ہے؟","answer":"کیونکہ معیار کم کرنے سے تفصیل کم ہوتی ہے مگر سائز وہی رہتا ہے۔ ڈائمینشن کم کرنا آخری حل ہے، تاکہ معیار زیادہ سے زیادہ بچے۔"},{"question":"فکسڈ ٹول اور کسٹم ٹارگٹ ٹول میں کیا فرق ہے؟","answer":"فکسڈ ٹول طے شدہ سائز دیتا ہے، جیسے 100 کلو بائٹ۔ کسٹم ٹول آپ کو کوئی بھی ہدف چننے دیتا ہے۔ اگر فارم کی حد طے ہو تو فکسڈ کافی ہے، ورنہ کسٹم چنیں۔"}];
